phase2Base <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "phase2Base",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "jmsequential",
                name = "phase2",
                version = c(0,1,0),
                options = options,
                results = phase2Results$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Phase II Multistage Design
#'
#' Single-arm phase II designs for a binary response: Simon's optimal, minimax 
#' and admissible two-stage designs, the exact single-stage design, Fleming's 
#' multistage test, and Bayesian monitoring with predictive (Lee & Liu) or 
#' posterior probabilities. Exact operating characteristics, and inference for 
#' observed data.
#' @param data .
#' @param design .
#' @param p0 .
#' @param p1 .
#' @param alpha .
#' @param power .
#' @param simonType .
#' @param admWeight .
#' @param nMax .
#' @param flemingStages .
#' @param flemingN .
#' @param prior .
#' @param priorA .
#' @param priorB .
#' @param bayesNmax .
#' @param bayesFirst .
#' @param bayesEvery .
#' @param thetaT .
#' @param thetaL .
#' @param thetaU .
#' @param analyse .
#' @param obsN .
#' @param obsX .
#' @param ciLevel .
#' @param candidates .
#' @param ocTable .
#' @param ocPlot .
#' @param boundPlot .
#' @param outcomePlot .
#' @param boundTraj .
#' @param boundProj .
#' @param boundHyp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$stages} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$candidates} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$oc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$observed} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ocPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$outcomePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$boundPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
phase2 <- function(
    data,
    design = "simon",
    p0 = 0.2,
    p1 = 0.4,
    alpha = 0.05,
    power = 0.8,
    simonType = "optimal",
    admWeight = 0.5,
    nMax = 0,
    flemingStages = 3,
    flemingN = "",
    prior = "meanp0",
    priorA = 1,
    priorB = 1,
    bayesNmax = 40,
    bayesFirst = 10,
    bayesEvery = 5,
    thetaT = 0.95,
    thetaL = 0.05,
    thetaU = 1,
    analyse = FALSE,
    obsN = 0,
    obsX = 0,
    ciLevel = 0.95,
    candidates = FALSE,
    ocTable = TRUE,
    ocPlot = TRUE,
    boundPlot = FALSE,
    outcomePlot = FALSE,
    boundTraj = TRUE,
    boundProj = TRUE,
    boundHyp = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("phase2 requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- phase2Options$new(
        design = design,
        p0 = p0,
        p1 = p1,
        alpha = alpha,
        power = power,
        simonType = simonType,
        admWeight = admWeight,
        nMax = nMax,
        flemingStages = flemingStages,
        flemingN = flemingN,
        prior = prior,
        priorA = priorA,
        priorB = priorB,
        bayesNmax = bayesNmax,
        bayesFirst = bayesFirst,
        bayesEvery = bayesEvery,
        thetaT = thetaT,
        thetaL = thetaL,
        thetaU = thetaU,
        analyse = analyse,
        obsN = obsN,
        obsX = obsX,
        ciLevel = ciLevel,
        candidates = candidates,
        ocTable = ocTable,
        ocPlot = ocPlot,
        boundPlot = boundPlot,
        outcomePlot = outcomePlot,
        boundTraj = boundTraj,
        boundProj = boundProj,
        boundHyp = boundHyp)

    analysis <- phase2Class$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

